module asyn_fifo #(
    parameter DEPTH = 16,
    parameter WIDTH = 8,
    parameter ADDR_WIDTH = $clog2(DEPTH)
) (
    input 					wclk,
    input 					rclk,
    input 					wrstn,
    input					rrstn,
    input 					winc,
    input 			 		rinc,
    input 		[WIDTH-1:0]	wdata,
    output wire				wfull,
    output wire				rempty,
    output reg [WIDTH-1:0]	rdata
);

reg [ADDR_WIDTH-1:0] waddr;
reg [ADDR_WIDTH-1:0] raddr;
reg [WIDTH-1:0] ram [0:DEPTH-1];
wire [ADDR_WIDTH-1:0] waddr_gray;
wire [ADDR_WIDTH-1:0] raddr_gray;

assign waddr_gray = waddr ^ (waddr >> 1);
assign raddr_gray = raddr ^ (raddr >> 1);

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        waddr <= 0;
    end else if (winc && !wfull) begin
        ram[waddr_gray] <= wdata;
        waddr <= waddr + 1;
    end
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        raddr <= 0;
    end else if (rinc && !rempty) begin
        raddr <= raddr + 1;
    end
end

assign wfull = (waddr_gray == (raddr_gray + DEPTH - 1)) || (waddr_gray == 0 && raddr_gray == DEPTH - 1);
assign rempty = (raddr_gray == waddr_gray);

assign rdata = ram[raddr_gray];

endmodule

module dual_port_RAM #(parameter DEPTH = 16, parameter WIDTH = 8)
(
    input      wclk,
    input      wenc,
    input  [$clog2(DEPTH)-1:0] waddr,
    input  [WIDTH-1:0] wdata,
    input      rclk,
    input      renc,
    input  [$clog2(DEPTH)-1:0] raddr,
    output reg [WIDTH-1:0] rdata
);

reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

always @(posedge wclk) begin
    if (wenc)
        RAM_MEM[waddr] <= wdata;
end

always @(posedge rclk) begin
    if (renc)
        rdata <= RAM_MEM[raddr];
end

endmodule
